            parts = listOf(
                StoryPart(1, "The Recipe without a Date", listOf("At the community centre, Amaka found a recipe card with ingredients but no date or name.", "The centre coordinator explained that the card came from a box of donated community records and that its owner was unknown.", "Amaka suggested creating a recipe calendar that would preserve contributions only with permission.")),
