                StoryPart(4, "Testing the Instructions", listOf("The group noticed that the recipe used measurements that might be unfamiliar to younger readers.", "An adult volunteer helped them clarify the measurements and identify an ingredient that needed an allergy note.", "They added a reminder that readers should check ingredients and follow safe food-handling guidance with an adult.")),
                StoryPart(5, "A Missing Month", listOf("The calendar had no contribution for one month, and the students worried that the project would look incomplete.", "The coordinator reminded them that the calendar did not need to force a contribution from anyone.", "Instead, they used the space for a note about seasonal produce and how availability can vary.")),
